import type { TypedRouteLocationRaw } from '@typed-router';

export function useRefreshAccountAndRedirect(redirectTo: TypedRouteLocationRaw = { name: 'account-canvasser' }) {
  const queryCache = useQueryCache();
  const { getSession } = useAuth();

  return async () => {
    await getSession();
    await queryCache.invalidateQueries({ key: ['account'], exact: true });
    await navigateTo(redirectTo);
  };
}
